	/**
	 * Faucet 製品データの取得（CSVデータ→連想配列へ）
	 * 製品データファイル読み込み後のCallback関数
	 * 処理終了後、各callback関数共通でsetup()を呼び出す
	 *
	 */
	initFaucet: function(data) {
// ENGINE.log('initFaucet() - start.');

		// 取得したテキストデータをCSV形式に変換
		data = ENGINE.SimulatorCommon.parseCSV(data);
		// CSV形式のデータをJSON形式のデータに変換
		ENGINE.Simulator.vars.faucet_list = ENGINE.SimulatorCommon.parseCSV2JSON(data);

		var product_id, series, shape, colour, colour_id, product_type;
		var colour_list = ENGINE.Simulator.settings['faucet_colour'];
		for(var i=0,max=ENGINE.Simulator.vars.faucet_list.length; i<max; i++) {

			// 製品タイプの取得
			product_type = ENGINE.Simulator.vars.faucet_list[i]['PRODUCT_TYPE'];


			// 製品品番をキーにした連想配列の生成
			product_id = ENGINE.Simulator.vars.faucet_list[i]['PRODUCT_ID'];
			ENGINE.Simulator.vars.faucet_master[product_id] = ENGINE.Simulator.vars.faucet_list[i];

			// OptionでPRODUCT_TYPEの絞り込みが設定されている場合
			if ( ENGINE.Simulator.vars.narrow_down_type && (ENGINE.Simulator.vars.narrow_down_type != product_type) ) {
				continue;
			}

			if ( (product_type == 'faucet') || (product_type == 'auto-faucet') ) {

				// seriesごとに分類した製品リストの生成
				series = ENGINE.Simulator.vars.faucet_list[i]['SERIES'];
				// - product_typeが存在しない場合、Objectの初期化
				if ( !ENGINE.SimulatorCommon.array_key_exists(product_type, ENGINE.Simulator.vars.faucet_list4series) ) {
					ENGINE.Simulator.vars.faucet_list4series[product_type] = {};
				}
				// - seriesが存在しない場合、Arrayの初期化
				if ( !ENGINE.SimulatorCommon.array_key_exists(series, ENGINE.Simulator.vars.faucet_list4series[product_type]) ) {
					ENGINE.Simulator.vars.faucet_list4series[product_type][series] = [];
				}
				ENGINE.Simulator.vars.faucet_list4series[product_type][series].push(ENGINE.Simulator.vars.faucet_list[i]);

				// shapeごとに分類した製品リスト
				shape  = ENGINE.Simulator.vars.faucet_list[i]['SHAPE'];
				// - product_typeが存在しない場合、Objectの初期化
				if ( !ENGINE.SimulatorCommon.array_key_exists(product_type, ENGINE.Simulator.vars.faucet_list4shape) ) {
					ENGINE.Simulator.vars.faucet_list4shape[product_type] = {};
				}
				// - seriesが存在しない場合、Arrayの初期化
				if ( !ENGINE.SimulatorCommon.array_key_exists(shape, ENGINE.Simulator.vars.faucet_list4shape[product_type]) ) {
					ENGINE.Simulator.vars.faucet_list4shape[product_type][shape] = [];
				}
				ENGINE.Simulator.vars.faucet_list4shape[product_type][shape].push(ENGINE.Simulator.vars.faucet_list[i]);

				// colourごとに分類した製品リスト
				for(var colour_cat in colour_list) {
					for(var colour in colour_list[colour_cat]) {
						colour_id = 'COLOUR_' + colour;
						// if (ENGINE.Simulator.vars.faucet_list[i][colour_id] == 1) {
						if (ENGINE.Simulator.vars.faucet_list[i][colour_id] != '') {
							if (ENGINE.Simulator.vars.faucet_list4colour[colour]) {
								ENGINE.Simulator.vars.faucet_list4colour[colour].push(ENGINE.Simulator.vars.faucet_list[i]);
							} else {
								ENGINE.Simulator.vars.faucet_list4colour[colour] = [];
								ENGINE.Simulator.vars.faucet_list4colour[colour].push(ENGINE.Simulator.vars.faucet_list[i]);
							}
						}
					}
				}
			}
		}

// ENGINE.log('initFaucet() : show faucet_list');
// ENGINE.log(ENGINE.Simulator.vars.faucet_list);
// ENGINE.log('initFaucet() : show faucet_master');
// ENGINE.log(ENGINE.Simulator.vars.faucet_master);
// ENGINE.log('initFaucet() : show faucet_list4series');
// ENGINE.log(ENGINE.Simulator.vars.faucet_list4series);
// ENGINE.log('initFaucet() : show faucet_list4shape');
// ENGINE.log(ENGINE.Simulator.vars.faucet_list4shape);
// ENGINE.log('initFaucet() : show faucet_list4colour');
// ENGINE.log(ENGINE.Simulator.vars.faucet_list4colour);



		// 初期処理の呼び出し
		ENGINE.Simulator.setup();

// ENGINE.log('initFaucet() - end.');
	},
