	/**
	 * Relationデータの取得（CSVデータ→連想配列へ）
	 * 製品データファイル読み込み後のCallback関数
	 * 処理終了後、各callback関数共通でsetup()を呼び出す
	 *
	 */
	initRelation: function(data) {
// ENGINE.log('-- get relation --');
		// 取得したテキストデータをCSV形式に変換
		var relation_list = ENGINE.SimulatorCommon.parseCSV(data);

		var lavatory_id, faucet_id;
		var faucet_relation_list    = {};
		var lavatory_relation_list = {};

// ENGINE.log(relation_list);
		var item = '';
		for(var i=2,imax=relation_list.length; i<imax; i++) {
			for(var j=1,jmax=relation_list[i].length; j<jmax; j++) {
				// 値がセットされている場合
				item = relation_list[i][j];
				if (item.trim() != '') {
					lavatory_id = relation_list[1][j];
					faucet_id   = relation_list[i][0];

					// Faucet品番のキーと組み合わせ可能なLavatory品番をキーからなる連想配列（検索時の組み合わせ確認）
					if (faucet_relation_list[faucet_id]) {
						faucet_relation_list[faucet_id][lavatory_id] = 1;
					} else {
						faucet_relation_list[faucet_id] = {};
						faucet_relation_list[faucet_id][lavatory_id] = 1;
					}

					// Lavatory品番のキーと組み合わせ可能なLavatory品番をキーからなる連想配列（検索時の組み合わせ確認）
					if (lavatory_relation_list[lavatory_id]) {
						lavatory_relation_list[lavatory_id][faucet_id] = 1;
					} else {
						lavatory_relation_list[lavatory_id] = {};
						lavatory_relation_list[lavatory_id][faucet_id] = 1;
					}
				}
			}
		}

		ENGINE.Simulator.vars.faucet_relation_list   = faucet_relation_list;
		ENGINE.Simulator.vars.lavatory_relation_list = lavatory_relation_list;
// ENGINE.log('-- faucet base --');
// ENGINE.log(ENGINE.Simulator.vars.faucet_relation_list);
// ENGINE.log('-- lavatory base --');
// ENGINE.log(ENGINE.Simulator.vars.lavatory_relation_list);

		// 初期処理の呼び出し
		ENGINE.Simulator.setup();
	},
	/**
	 *
	 *
	 */
	initFaucetControllerRelation: function(data) {

		// 取得したテキストデータをCSV形式に変換
		var relation_list = ENGINE.SimulatorCommon.parseCSV(data);

		var relation = {};

		var faucet_id, power_type_ecopower, power_type_ac, power_type_dc, power_type_water_heater;
		var str_power_type_ecopower, str_power_type_ac, str_power_type_dc, str_power_type_water_heater;

		for(var i=0,max=relation_list.length; i<max; i++) {
			// 1行目はタイトル行
			if (i < 1) {
				continue;
			}

			faucet_id = relation_list[i][0];
			str_power_type_ecopower = relation_list[i][1] + '';
			str_power_type_ac = relation_list[i][2] + '';
			str_power_type_dc = relation_list[i][3] + '';
			str_power_type_water_heater = relation_list[i][4] + '';

			power_type_ecopower = (str_power_type_ecopower.trim() != '')?true:false;
			power_type_ac = (str_power_type_ac.trim() != '')?true:false;
			power_type_dc = (str_power_type_dc.trim() != '')?true:false;
			power_type_water_heater = (str_power_type_water_heater.trim() != '')?true:false;

			relation[faucet_id] = {
				'ecopower' : power_type_ecopower,
				'ac' : power_type_ac,
				'dc' : power_type_dc,
				'water-heater' : power_type_water_heater,
			};
		}

		ENGINE.Simulator.vars.faucet_controller_relation_list = relation;

		// 初期処理の呼び出し
		ENGINE.Simulator.setup();
	},
