	/**
	 * ContollerUnitとOptionの組み合わせリスト
	 *
	 */
	initControllerOptionRelation: function(data) {
		// 取得したテキストデータをCSV形式に変換
		var relation_list = ENGINE.SimulatorCommon.parseCSV(data);

		var relation = {};

		var power, temperature, controller_unit_id, controller_option_id;
		var series, size, flow, product_id; // US版で使用

		// 機能部切替時、品番を切り替える場合（US）
		if (ENGINE.Simulator.settings['faucet-option-change-type'] == 'product') {
			for(var i=0,max=relation_list.length; i<max; i++) {
				// 1行目はタイトル行
				if (i < 1) {
					continue;
				}
				series               = (relation_list[i][0] + '').trim();
				size                 = (relation_list[i][1] + '').trim();
				power                = (relation_list[i][2] + '').trim();
				temperature          = (relation_list[i][3] + '').trim();
				flow                 = (relation_list[i][4] + '').trim();
				product_id           = (relation_list[i][5] + '').trim();
				controller_unit_id   = (relation_list[i][6] + '').trim();

				if (temperature == '') {
					temperature = 'none';
				}
				if (flow == '') {
					flow = 'none';
				}

				if (!ENGINE.SimulatorCommon.array_key_exists(series, relation)) {
					relation[series] = {};
				}
				if (!ENGINE.SimulatorCommon.array_key_exists(size, relation[series])) {
					relation[series][size] = {};
				}
				if (!ENGINE.SimulatorCommon.array_key_exists(power, relation[series][size])) {
					relation[series][size][power] = {};
				}
				if (!ENGINE.SimulatorCommon.array_key_exists(flow, relation[series][size][power])) {
					relation[series][size][power][flow] = {};
				}

				relation[series][size][power][flow][temperature] = {
					product_id: product_id,
					controller_unit_id: controller_unit_id,
				};
			}

		// 通常
		} else {
			for(var i=0,max=relation_list.length; i<max; i++) {
				// 1行目はタイトル行
				if (i < 1) {
					continue;
				}

				power                = (relation_list[i][0] + '').trim();
				temperature          = (relation_list[i][1] + '').trim();
				controller_unit_id   = (relation_list[i][2] + '').trim();
				controller_option_id = (relation_list[i][3] + '').trim();

				if (!ENGINE.SimulatorCommon.array_key_exists(power, relation)) {
					relation[power] = {};
				}

				relation[power][temperature] = {
					controller_unit_id: controller_unit_id,
					controller_option_id: controller_option_id,
				};
			}
		}

		ENGINE.Simulator.vars.controller_option_relation_list = relation;

		// 初期処理の呼び出し
		ENGINE.Simulator.setup();

	},

