			// 画面遷移履歴の設定
			// 戻る(Back)処理
			if (target_id == 'back') {
				// 前の画面IDの取得
				target_id  = ENGINE.Simulator.popPanalHistory();

			// 同画面遷移はSKIP
			} else if (target_id == current_panel_id) {

			// それ以外の処理
			} else {
				// 画面遷移処理の呼び出し（共通処理）
				ENGINE.Simulator.registPanelHistory(target_id);
			}

			// Favorite以外の場合、SPナビの変更
			if (target_id != 'favorite') {
				ENGINE.Simulator.swapSpNavi('plan');
			}


			// TOPの場合、リセット処理
			if (target_id == 'top') {
				ENGINE.Simulator.resetPanalHistory();
				ENGINE.Simulator.moveTop();
			}

			// <body>タグに表示画面固有のclassを追加
			$('body').removeClass('uq_faucet-lavatory-' + current_panel_id).addClass('uq_faucet-lavatory-' + target_id);
			if (target_id == 'top') {
				$('body').removeClass('is_underlayer');
			} else {
				$('body').addClass('is_underlayer');
			}

			// 画面展開
			ENGINE.Simulator.panel_list[current_panel_id].removeClass('is-active');
			ENGINE.Simulator.panel_list[target_id].addClass('is-active');
			ENGINE.Simulator.active_panel_id = target_id;

// ENGINE.log('after - history');
// ENGINE.log(ENGINE.Simulator.panel_history_list);

			// ステップフローの更新
			ENGINE.Simulator.resetFlowNavi(target_id, current_panel_id);

			// 結果場面・Favarite詳細の場合、結果表示用の処理を呼び出す
			if ( (target_id == 'result') || (target_id == 'saved') ) {
				ENGINE.SimulatorCommon.stageFit();
			}

			// スクロール位置のリセット
      $('body,html').animate({
        scrollTop: 0
      }, 1);

// ENGINE.log('# condition after terminateTransitionFunc()');
// ENGINE.log(ENGINE.Simulator.condition);

