		// リストの表示
		var $list_holder = $('#faucet_series_list');
		$list_holder.html(code_block);

		// リンクの初期化
		ENGINE.Simulator.initTransitionLink($list_holder);

// ENGINE.log('moveFaucetSeries() - end.');

