		var selected_lavatory = ENGINE.Simulator.condition['lavatory-product']?ENGINE.Simulator.condition['lavatory-product']:false;
		var valid_shape_list = {};
		if (selected_lavatory) {
			// 組み合わせ可能なfaucetの品番リストを取得
			var refine_faucet_list = ENGINE.Simulator.vars.lavatory_relation_list[selected_lavatory];
			var refine_faucet_product, refine_faucet_shape;

			// 組み合わせ可能なfaucetの品番リストに格納されている品番数分LOOP
			for(var refine_faucet_id in refine_faucet_list) {
				// faucet製品マスタより製品情報を取得
				refine_faucet_product = ENGINE.Simulator.vars.faucet_master[refine_faucet_id];
				// 製品に紐づくShapeを取得し、連想配列に可能（表示、非表示の制御に使用する）
				if (refine_faucet_product && refine_faucet_product['SHAPE']) {
					refine_faucet_shape = refine_faucet_product['SHAPE'];
					valid_shape_list[refine_faucet_shape] = true;
				}
			}
		}

		var code_anchor_block = '';
		var code_block  = '';
		var code_anchor = "";
		var code_list   = "";

