				if (!ENGINE.SimulatorCommon.array_key_exists(shape, ENGINE.Simulator.vars.faucet_list4shape[product_type]) || (ENGINE.Simulator.vars.faucet_list4shape[product_type][shape].length == 0)) {
					continue;
				}

