				faucet = ENGINE.Simulator.vars.faucet_master[faucet_id];

				// code_list += '<li><a href="#faucet-product" data-transition-link="faucet-product" data-search-type="faucet-colour" data-search-id="' + colour + '">';
				code_list_child += '<li><a href="#faucet-series" data-transition-link="faucet-series" data-search-type="faucet-colour" data-search-id="' + colour + '">';
				code_list_child += '<div class="m_colour__box">';
