	/**
	 * 結果画面の表示
	 *
	 */
	moveResult: function() {
ENGINE.log('moveResult() - start.');
ENGINE.log('# condition');
ENGINE.log(ENGINE.Simulator.condition);
ENGINE.log(ENGINE.Simulator.flow_nav);

		// Faucet製品情報の取得
		var faucet_id = ENGINE.Simulator.condition['faucet-product'];
		var faucet_colour = ENGINE.Simulator.condition['faucet-colour'];

		// changeから再選択しようとして中断した場合の処理
		if ( (faucet_colour == '') && (ENGINE.Simulator.condition['faucet-colour-before']) ) {
			faucet_colour = ENGINE.Simulator.condition['faucet-colour-before'];
			ENGINE.Simulator.condition['faucet-colour-before'] = '';
		}

		// SDをセットするかどうかの判断
// ENGINE.log('moveResult() - soapdispenser [' + ENGINE.Simulator.condition['faucet-option-soapdispenser'] + ']');
// ENGINE.log(ENGINE.Simulator.condition);
		var show_soapdispenser = (ENGINE.Simulator.condition['faucet-option-soapdispenser'] == 'yes')?true:false;

		// Lavatory製品情報の取得
		var lavatory_id = ENGINE.Simulator.condition['lavatory-product'];


		// 組み合わせリストに存在する場合のみ
		var soapdispenser_id, soaptank_id;
		if (show_soapdispenser && ENGINE.SimulatorCommon.array_key_exists(faucet_id, ENGINE.Simulator.vars.faucet_sd_relation_list)) {
			soapdispenser_id = ENGINE.Simulator.vars.faucet_sd_relation_list[faucet_id]['soapdispenser_id'];
			soaptank_id = ENGINE.Simulator.vars.faucet_sd_relation_list[faucet_id]['soaptank_id'];

			if (soapdispenser_id) {
				ENGINE.Simulator.condition['soapdispenser-product'] = soapdispenser_id;
			}
			if (soaptank_id) {
				ENGINE.Simulator.condition['soaptank-product'] = soaptank_id;
			}
		} else {
			ENGINE.Simulator.condition['soapdispenser-product'] = '';
			ENGINE.Simulator.condition['soaptank-product'] = '';
		}

		// Faucet Option変更時、切り替わる対象がControllerのときのみ処理する
		if (ENGINE.Simulator.settings['faucet-option-change-type'] == 'controller') {
// ENGINE.log('--- controller option relation');
			var controller_option_relation_list = ENGINE.Simulator.vars['controller_option_relation_list'];
// ENGINE.log(controller_option_relation_list);

			var power = ENGINE.Simulator.condition['faucet-option-power'];

			// FaucetがEWATERのように、AC選択時に別のControllerを変換させる場合の処理
			// settings.jsonで定義
			var convert_faucet_power_list = ENGINE.Simulator.settings['convert-faucet-power-list'];
			if (ENGINE.SimulatorCommon.array_key_exists(faucet_id, convert_faucet_power_list) && ENGINE.SimulatorCommon.array_key_exists(power, convert_faucet_power_list[faucet_id])) {
				power = convert_faucet_power_list[faucet_id][power];
			}

			var temperature = ENGINE.Simulator.condition['faucet-option-temperature'];
			var controller_unit_id, controller_option_id;
			if (ENGINE.SimulatorCommon.array_key_exists(power, controller_option_relation_list) && ENGINE.SimulatorCommon.array_key_exists(temperature, controller_option_relation_list[power])) {

				controller_unit_id   = controller_option_relation_list[power][temperature]['controller_unit_id'];
				controller_option_id = controller_option_relation_list[power][temperature]['controller_option_id'];

				if (controller_unit_id) {
					ENGINE.Simulator.condition['controller-unit-product'] = controller_unit_id;
				}
				if (controller_option_id) {
					ENGINE.Simulator.condition['controller-option-product'] = controller_option_id;
				}
			}
		}


		// 結果画面用コード（PC／SP共通）の取得
		var $result = $('#result_panel');
		var code_result = ENGINE.Simulator.generateCodeResult('m_result', faucet_id, faucet_colour, lavatory_id, show_soapdispenser);

		$result.html(code_result);
		ENGINE.Simulator.initActionLink($result);
		ENGINE.Simulator.initTransitionLink($result);

		// スマホ用商品リストの表示
		var $sp_result = $('#sp_result_list');
		var code_result_sp = ENGINE.Simulator.generateCodeSelectedList('result');
		$sp_result.html(code_result_sp);

		ENGINE.Simulator.initActionLink($sp_result);
		ENGINE.Simulator.initTransitionLink($sp_result);


		// [START] Tracking
		if (ENGINE.SimulatorTracking && ENGINE.SimulatorTracking.send && (typeof ENGINE.SimulatorTracking.send == 'function')) {
			// Trackingパラメータの取得
			// ※連想配列で定義されているキーをENGINE.Simulator.conditionの設定されている値から取得
			// ※top-selectが設定されている内容は、TOPページで何を選択されたかをセットする（flow_nav.first_stepから判断）
			var tracking_vars = {
				'top-faucet-series' : 'top-select',
				'top-faucet-shape'  : 'top-select',
				'top-faucet-colour' : 'top-select',
				'top-lavatory'      : 'top-select',
				'fid'               : 'faucet-product',
				'fc'                : 'faucet-colour',
				'sdid'              : 'soapdispenser-product',
				'stid'              : 'soaptank-product',
				'cuid'              : 'controller-unit-product',
				'coid'              : 'controller-option-product',
				'lid'               : 'lavatory-product',
			};

			// 送信用パラメータの設定
			var tracking = {};
			var tracking_cid  = '';
			var tracking_cval = '';
			var tracking_pid  = '';

// ENGINE.log('--- [START] generate trackging param ---');

			for(var tracking_id in tracking_vars) {
				tracking_cid  = tracking_vars[tracking_id];
				tracking_cval = '';
				tracking_pid  = '';

// ENGINE.log('param [' + tracking_id + '] => [' + tracking_cid + ']');

				// TOPでの選択内容の取得
				if (tracking_cid == 'top-select') {
// ENGINE.log('is top select');
// ENGINE.log('param [' + ENGINE.Simulator.flow_nav['first-step'] + ']');

					// faucet-series / faucet-shape / faucet-colour / lavatory-shapeがセットされている
					tracking_pid = 'top-' + ENGINE.Simulator.flow_nav['first-step'];
					// lavatory-shapeの場合、tracking用に読み替える
					if (ENGINE.Simulator.flow_nav['first-step'] == 'lavatory-shape') {
						tracking_pid = 'top-lavatory';
					}

// ENGINE.log('convvert key [' + tracking_pid + ']');

					// フラグを立てる
					if (ENGINE.SimulatorCommon.array_key_exists(tracking_pid, tracking_vars)) {
						tracking[tracking_pid] = 1;
					}

				// 上記以外
				} else {
// ENGINE.log('is other');

					tracking[tracking_id] = ENGINE.Simulator.condition[tracking_cid];
// ENGINE.log('param [' + tracking_id + '] => [' + tracking_cid + '] => [' + ENGINE.Simulator.condition[tracking_cid] + ']');

				}
// ENGINE.log('--------------------------------------');
			}

			// 設定値の正規化
			for(var id in tracking) {
				if ((tracking[id] == 'null') || (tracking[id] == null) || (tracking[id] == 'undefined')) {
					tracking[id] = '';
				}
			}

			// UUID
ENGINE.log('# get uuid');
			var cookie_id = 'faucet-lavatory_tracking';
			var uuid = false;
			if ($.cookie(cookie_id)) {
				uuid = $.cookie(cookie_id);
ENGINE.log('from cookie : ' + uuid);
			} else {
				uuid = ENGINE.SimulatorCommon.getUniqueID();
				$.cookie(cookie_id, uuid, {expires: ENGINE.Simulator.settings['cookie_expired']});
ENGINE.log('generate new id : ' + uuid);
			}

			// 送信
			tracking['uuid'] = uuid;
			tracking['type'] = 'f'; // s:shower, f:faucet-lavatory, t:touchless-faucet-lavatory
			// Touchlessの場合
			if (ENGINE.Simulator.vars.is_narrow_down && ENGINE.Simulator.vars.narrow_down_type == 'auto-faucet') {
				tracking['type'] = 't';
				tracking['is-touchless'] = 1;
			}

			ENGINE.SimulatorTracking.send(tracking);

// ENGINE.log('# condition');
// ENGINE.log('--------------------------------------');
// ENGINE.log(ENGINE.Simulator.condition);
// ENGINE.log('--- [END] generate trackging param ---');
		}
		// [END] Tracking


// ENGINE.log('# condition after');
// ENGINE.log(ENGINE.Simulator.condition);
// ENGINE.log('moveResult() - end.');
	},

