// ENGINE.log(faucet);

		// カウンターが分離されているか
		var is_separate_counter = (lavatory && lavatory['IS_SEPARETE_COUNTER'])?true:false;

		// outsetかどうか（画像の重ね順）
		// Shapeがvessel_outset、galalato以外の場合、カウンターあり画像のためinset / outset に関わらず、金具が上になる (inset扱いとする)
		var is_outset = (lavatory && (lavatory['CATEGORY_2'] == 'outset') && ((lavatory_shape == 'vessel_outset') || (lavatory_shape == 'galalato') || ( ((lavatory_shape == 'self_rimming') || (lavatory_shape == 'semi_reccesed')) && is_separate_counter)))?true:false;
		// var is_outset = (lavatory && (lavatory['CATEGORY_2'] == 'outset') && ((lavatory_shape == 'vessel_outset') || (lavatory_shape == 'galalato') || ( (lavatory_shape == 'semi_reccesed') && is_separate_counter)))?true:false;

