	/**
	 * 結果表示用URLパラメータの生成
	 *
	 */
	generateURLParameter(data) {

		data = data?data:ENGINE.Simulator.condition;

		var param = [];

		var selected_faucet        = data['faucet-product'];
		var selected_faucet_colour = data['faucet-colour'];
		var selected_lavatory      = data['lavatory-product'];

		var selected_faucet_option_flow          = data['faucet-option-flow'];
		var selected_faucet_option_power         = data['faucet-option-power'];
		var selected_faucet_option_soapdispenser = data['faucet-option-soapdispenser'];
		var selected_faucet_option_temperature   = data['faucet-option-temperature'];

		var selected_soapdispenser     = data['soapdispenser-product'];
		var selected_soaptank          = data['soaptank-product'];
		var selected_controller_unit   = data['controller-unit-product'];
		var selected_controller_option = data['controller-option-product'];

		// Lavagoryの場合品番に#が使用されているものがあるためファイル名変換を行う
		selected_lavatory = ENGINE.Simulator.converProductID2URL(selected_lavatory);
	// ENGINE.log('generateURLParameter() : ' + selected_lavatory);

		if (selected_faucet) {
			param.push('fid=' + selected_faucet);
		}
		if (selected_faucet_colour) {
			param.push('fc=' + selected_faucet_colour);
		}
		if (selected_lavatory) {
			param.push('lid=' + selected_lavatory);
		}

		// AF関連選択肢
		if (selected_faucet_option_flow) {
			param.push('fof=' + selected_faucet_option_flow);
		}
		if (selected_faucet_option_power) {
			param.push('fop=' + selected_faucet_option_power);
		}
		if (selected_faucet_option_soapdispenser) {
			param.push('fosd=' + selected_faucet_option_soapdispenser);
		}
		if (selected_faucet_option_temperature) {
			param.push('fot=' + selected_faucet_option_temperature);
		}

		// AF関連品番
		if (selected_soapdispenser) {
			param.push('sdid=' + selected_soapdispenser);
		}
		if (selected_soaptank) {
			param.push('stid=' + selected_soaptank);
		}
		if (selected_controller_unit) {
			param.push('cuid=' + selected_controller_unit);
		}
		if (selected_controller_option) {
			param.push('coid=' + selected_controller_option);
		}

		var qstr = '';
		if (param.length > 0) {
			qstr = '?' + param.join('&');
		}

		return qstr;
	},

	/**
	 * Lavagoryの場合品番に#が使用されているものがあるためファイル名変換を行う
	 *
	 */
	converProductID2URL: function(product_id, is_reverse) {
		var result = product_id + '';
		if (is_reverse) {
			result = result.replace('-', '#');
		} else {
			result = result.replace('#', '-');
		}

		return result;
	},
  /**
   * Lavagoryの場合品番に()が使用されているものがあるためファイル名変換を行う
   * ※background-image対応
   *
   */
  converProductID2Image: function converProductID2Image(product_id) {
    var result = product_id + '';

    result = result.replace('(', '');
    result = result.replace(')', '');

    return result;
  },

	/**
	 * Faucetの金額取得
	 * Add 2021.04 Colourに応じて金額を変更する必要あり
	 *
	 */
	getColourPrice: function(product, selected_colour) {
		var price = product['PRICE'];
// console.log('start - getColourPrice()');
// console.log(product);
// console.log('before :: ' + price);
// console.log('before :: ' + selected_colour);

		// Faucetの場合のみ
		if ((product['PRODUCT_TYPE'] == 'faucet') || (product['PRODUCT_TYPE'] == 'auto-faucet')) {
// console.log('judge1');

			// setting.jsonで設定がある場合のみ
			if (ENGINE.Simulator.settings['faucet_price_type']) {
// console.log('judge2');
				// 結果画面のFaucet「change」をクリックした場合、色選択を解除する仕様のため、変更前のColourを取得
				if(!selected_colour) {
					selected_colour = ENGINE.Simulator.condition['faucet-colour-before'];
				}

				var colour_price = product['COLOUR_' + selected_colour];
// console.log(colour_price);
				// 半角数字の場合のおみ
				if (colour_price && colour_price.match(/^[0-9]+$/)) {
// console.log('judge3');
					price = colour_price;
				}
			}
		}
// console.log('after :: ' + price);
// console.log('end - getColourPrice()');

		return price;
	}

